<script lang="ts">
 import Modal from './Modal.svelte';import Feedback from './Feedback.svelte';import {Button} from '#lib/components/ui/button/index.ts';import {authApi} from '#lib/api/auth.ts';import {apiMessage} from '#lib/admin/scheduling.ts';
 let {open=$bindable(false)}:{open?:boolean}=$props();let current=$state(''),next=$state(''),confirm=$state(''),busy=$state(false),error=$state(''),done=$state(false);
 async function save(e:SubmitEvent){e.preventDefault();error='';if(next!==confirm){error='兩次新密碼不一致';return;}busy=true;try{await authApi.changePassword(current,next);current='';next='';confirm='';done=true;}catch(e){error=apiMessage(e,'修改密碼失敗');}finally{busy=false;}}
</script>
<Modal bind:open title="修改密碼" {busy}><form onsubmit={save} class="space-y-4"><Feedback {error} message={done?'密碼已更新，下次登入請使用新密碼。':''}/>{#if !done}<fieldset disabled={busy} class="space-y-4"><label>目前密碼<input type="password" bind:value={current} autocomplete="current-password" required/></label><label>新密碼<input type="password" bind:value={next} autocomplete="new-password" minlength="8" required/></label><label>確認新密碼<input type="password" bind:value={confirm} autocomplete="new-password" minlength="8" required/></label></fieldset>{/if}<div class="flex justify-end gap-2"><Button variant="outline" disabled={busy} onclick={()=>open=false}>{done?'關閉':'取消'}</Button>{#if !done}<Button type="submit" disabled={busy}>{busy?'儲存中…':'儲存密碼'}</Button>{/if}</div></form></Modal>
